SELECT ,
       c.category_name,
       u.real_name AS host_name,
       u.phone     AS host_phone
FROM house h
LEFT JOIN house_category c ON h.category_id = c.id
LEFT JOIN sys_user u       ON h.host_id = u.id


        AND (h.title LIKE CONCAT('%', #{keyword}, '%')
