        AND h.category_id = #{categoryId}


        AND h.city = #{city}


        AND h.price >= #{minPrice}


        AND h.price <= #{maxPrice}


        AND h.max_guest >= #{guestNum}


        AND h.status = #{status}


        AND h.host_id = #{hostId}



